// Logout.js (React Component)

import React from 'react';
import { useNavigate } from 'react-router-dom'; // Use useNavigate from React Router v6
import { logout } from '../services/api'; // Correct path to api.js based on your folder structure

const Logout = () => {
    const navigate = useNavigate(); // Initialize the useNavigate hook for navigation

    // Handle logout process
    // In your logout function
const handleLogout = async () => {
    try {
       const response = await logout();  // Assume this sends the request
       console.log(response);
       localStorage.removeItem('token'); // Remove from localStorage
       sessionStorage.removeItem('token'); // Remove from sessionStorage
       deleteCookie('token')
       // If the response is valid, handle logout
       if (response && response.message) {
          localStorage.removeItem('token');
          navigate('/login');  // Redirect to login page
       } else {
          console.error('Logout failed: Invalid response');
       }
    } catch (error) {
       console.error('Logout failed:', error);
    }
 };
 

    return (
        <div>
            <h1>You have been logged out</h1>
            <p>Click the button below to logout.</p>
            <button onClick={handleLogout}>Logout</button>
        </div>
    );
};

export default Logout;
